-- Production's row-level-security policies (pg_policies, metadata only),
-- mirrored so the browser sees exactly what it sees in production. Every
-- existing public policy is dropped first: the migration history and the live
-- database disagree, and production is the one the app is written against.
DO $$ DECLARE r record; BEGIN
  FOR r IN SELECT policyname, tablename FROM pg_policies WHERE schemaname = 'public' LOOP
    EXECUTE format('DROP POLICY %I ON public.%I', r.policyname, r.tablename);
  END LOOP;
END $$;
CREATE POLICY "Access own company data" ON public.daily_logs AS PERMISSIVE FOR ALL TO public USING (project_id IN (SELECT projects.id FROM projects WHERE projects.gc_company_id = (SELECT profiles.company_id FROM profiles WHERE profiles.id = auth.uid()))) WITH CHECK (project_id IN (SELECT projects.id FROM projects WHERE projects.gc_company_id = (SELECT profiles.company_id FROM profiles WHERE profiles.id = auth.uid())));
